// Tests for public/homewalk-plan.js against the bundle the iOS app writes
// (test-fixtures/homewalk-sample.homewalk, generated by FixtureExportTests).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { evaluate, renderSVG, report, timeline, videoOffset } from './public/homewalk-plan.js';

const doc = JSON.parse(fs.readFileSync('test-fixtures/homewalk-sample.homewalk/plan.json', 'utf8'));

test('fixture is the schema the app writes', () => {
  assert.equal(doc.schemaVersion, 1);
  for (const key of ['rooms', 'doorways', 'floor', 'events', 'observations', 'mismatches', 'inProgress', 'media', 'alignmentChecks']) assert.ok(key in doc, key);
  assert.equal(doc.rooms.length, 3);
  assert.ok(doc.rooms.every(r => r.editedPolygon.length === 4 && r.walkTrail.length > 0 && r.walkPath.length > 0));
});

test('evaluate reports tape error per wall and shared-wall snaps', () => {
  const ev = evaluate(doc);
  const kitchen = ev.rooms.find(r => r.name === 'Kitchen');
  assert.ok(Math.abs(kitchen.width - 4.5) < 1e-6, 'box = 4 m walk + 0.5 m pad, door tap pins one side');
  assert.ok(Math.abs(kitchen.depth - 4.0) < 1e-6);
  assert.deepEqual(kitchen.tape, { width: 4.05, depth: 3.02 });
  assert.ok(Math.abs(kitchen.errW - (4.5 - 4.05) / 4.05 * 100) < 1e-9);
  assert.equal(kitchen.snap, null, 'first room has no neighbour');
  const hall = ev.rooms.find(r => r.name === 'Hallway');
  assert.ok(Math.abs(hall.snap - 0.3) < 1e-6, 'hallway was pulled 30 cm onto the kitchen wall');
  const bedroom = ev.rooms.find(r => r.name === 'Bedroom');
  assert.equal(bedroom.tape, null);
  assert.equal(bedroom.errW, null);
  assert.equal(ev.summary.roomsWithTape, 2);
  assert.equal(ev.summary.roomsWithin10Pct, 0, 'pad makes every wall long in this synthetic walk');
  assert.ok(Math.abs(ev.gridAngleDeg - 20) < 0.5, 'first room walked at 20° to the AR axes');
});

test('doors connect rooms and the return-to-door check is reported', () => {
  const ev = evaluate(doc);
  assert.equal(ev.doors.length, 2);
  assert.ok(ev.doors.every(d => d.connected));
  assert.deepEqual(ev.doors[0].rooms, ['Kitchen', 'Hallway']);
  assert.deepEqual(ev.doors[1].rooms, ['Hallway', 'Bedroom']);
  assert.equal(ev.alignmentChecks.length, 1);
  assert.deepEqual(ev.alignmentChecks[0].rooms, ['Hallway', 'Bedroom']);
  assert.ok(ev.alignmentChecks[0].distance > 0.15 && ev.alignmentChecks[0].distance < 0.25, `drift ${ev.alignmentChecks[0].distance}`);
  assert.equal(ev.summary.unresolvedDoors, 0);
  assert.equal(ev.mismatches.length, 0);
});

test('timeline rows carry video offsets from the media anchor', () => {
  const rows = timeline(doc);
  assert.ok(rows.length >= 6);
  assert.equal(rows[0].type, 'walkStarted');
  assert.equal(rows[0].sinceStart, 0);
  assert.ok(rows.some(r => r.type === 'roomFinished' && r.rooms.includes('Kitchen')));
  assert.ok(rows.some(r => r.type === 'note' && /Dishwasher/.test(r.label)));
  const finished = rows.filter(r => r.type === 'roomFinished');
  assert.ok(finished.every(r => r.videoOffset != null && r.videoOffset >= 0), 'events during the video map into it');
  assert.equal(videoOffset(doc, doc.media.videoStartedAt - 5), null);
  assert.equal(videoOffset(doc, doc.media.videoEndedAt + 5), null);
});

test('svg draws every room polygon, both doors, the trail and the drift marker', () => {
  const svg = renderSVG(doc, { selected: doc.rooms[1].id, showTrail: true, showPath: true });
  assert.ok(svg.startsWith('<svg'));
  assert.equal((svg.match(/<polygon /g) ?? []).length, 3);
  assert.equal((svg.match(/data-room=/g) ?? []).length, 3);
  assert.ok(svg.includes('Kitchen') && svg.includes('Hallway') && svg.includes('Bedroom'));
  assert.ok(svg.includes('4.50 × 4.00 m'));
  assert.ok(svg.includes('tape 4.05 × 3.02'));
  assert.equal((svg.match(/stroke-dasharray="5 4"/g) ?? []).length, 3, 'one walk trail per room');
  assert.equal((svg.match(/stroke="#2b5d8a"/g) ?? []).length, 3, 'one phone path per room');
  assert.equal((svg.match(/stroke="#c49a3c"/g) ?? []).length, 2, 'two connected doors');
  assert.ok(/\d+ cm<\/text>/.test(svg), 'drift label');
  assert.ok(svg.includes('stroke="#e46b3b" stroke-width="4"'), 'selected room highlighted');
});

test('report is a readable table with the proposed targets', () => {
  const text = report(doc);
  assert.ok(text.includes('Kitchen'));
  assert.ok(text.includes('+11%'));
  assert.ok(/door check  Hallway ↔ Bedroom: \d+ cm off/.test(text));
  assert.ok(text.includes('median wall error ≤ 10%'));
});
